import { test } from 'node:test';
import assert from 'node:assert/strict';
import { reverse, slug } from '../src/strings.mjs';

test('reverse ascii', () => { assert.equal(reverse('hello'), 'olleh'); });
test('slug basic', () => { assert.equal(slug('Hello World'), 'hello-world'); });
test('reverse combining mark', () => {
  // 'e\u0301' is e + combining acute. Reverse should keep them together.
  const input = 'a' + '\u0065\u0301';
  const out = reverse(input);
  assert.equal(out, '\u0065\u0301' + 'a');
});

